import{c as l,Q as s,j as o,m as r}from"./chunks/framework.rWdQudnF.js";const e=JSON.parse('{"title":"架构设计方法","description":"","frontmatter":{"title":"架构设计方法"},"headers":[],"relativePath":"综合知识/架构设计/架构设计方法.md","filePath":"综合知识/架构设计/架构设计方法.md","lastUpdated":null}'),n={name:"综合知识/架构设计/架构设计方法.md"};function a(i,t,g,c,u,p){return s(),o("div",null,[...t[0]||(t[0]=[r('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] ABSD（基于架构的软件设计）— 六个子过程</li><li>[ ] DSSA（特定领域软件架构）— 领域分析/设计/实现</li><li>[ ] 4+1 视图模型</li><li>[ ] 架构文档化</li><li>[ ] 软件架构复用（机会复用/系统复用/水平式/垂直式）</li><li>[ ] 架构复审与演化</li><li>[ ] 软件系统四大基本功能 + 三硬件构件</li><li>[ ] 构件组装与架构失配（构件失配/连接子失配/全局失配）</li><li>[ ] 设计模式三分类（创建型/结构型/行为型）</li><li>[ ] ANSI/IEEE 1471-2000 标准</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、absd-—-基于架构的软件设计" tabindex="-1">一、ABSD — 基于架构的软件设计 <a class="header-anchor" href="#一、absd-—-基于架构的软件设计" aria-label="Permalink to &quot;一、ABSD — 基于架构的软件设计&quot;">​</a></h3><blockquote><p>ABSD 方法是由<strong>商业、质量和功能需求</strong>的组合驱动的，是一个<strong>自顶向下、递归细化</strong>的方法，直到能产生<strong>软件构件和类</strong>。</p></blockquote><p><strong>ABSD 方法的三个基础：</strong></p><ol><li>对系统进行功能分解</li><li>采用<strong>架构策略</strong>实现质量属性与商业需求</li><li>采用软件模板设计软件结构</li></ol><p><strong>六个子过程：</strong></p><ol><li><strong>架构需求</strong> — 获取需求</li><li><strong>架构设计</strong> — 设计方案</li><li><strong>架构文档化</strong> — 输出架构规格说明和测试架构需求的质量设计说明书</li><li><strong>架构复审</strong> — 标识潜在风险，及早发现架构设计中的缺陷和错误</li><li><strong>架构实现</strong> — 编码实现</li><li><strong>架构演化</strong> — 应对需求变化，修改应用架构满足新需求</li></ol><hr><h3 id="二、dssa-—-特定领域软件架构" tabindex="-1">二、DSSA — 特定领域软件架构 <a class="header-anchor" href="#二、dssa-—-特定领域软件架构" aria-label="Permalink to &quot;二、DSSA — 特定领域软件架构&quot;">​</a></h3><blockquote><p>DSSA 是特定应用领域中为一组应用提供组织结构参考的<strong>标准软件架构</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>阶段</th><th>目标</th><th>产出</th></tr></thead><tbody><tr><td><strong>领域分析</strong></td><td>获得<strong>领域模型</strong>，描述领域中系统间的共同需求</td><td>领域模型</td></tr><tr><td><strong>领域设计</strong></td><td>获得<strong>特定领域软件架构（DSSA）</strong></td><td>领域架构</td></tr><tr><td><strong>领域实现</strong></td><td>开发和组织可重用信息，实现基础软件架构</td><td>可重用构件/资产</td></tr></tbody></table><p><strong>四类参与角色：</strong></p><ol><li><strong>领域专家</strong> — 提供领域知识</li><li><strong>领域分析者</strong> — 控制领域分析过程，进行知识获取，组织领域模型</li><li><strong>领域设计者</strong> — 根据领域模型开发领域设计，验证设计的准确性和一致性</li><li><strong>领域实现者</strong> — 实现可重用资产</li></ol><p><strong>DSSA 三级层次：</strong></p><ul><li>领域开发环境 → <strong>应用工程师</strong>主要在领域特定应用开发环境中工作</li><li>领域特定应用开发环境</li><li>应用执行环境</li></ul><p><strong>垂直域 vs 水平域：</strong></p><ul><li><strong>垂直域</strong>：定义了一个特定的系统族，包含整个系统族内的多个系统</li><li><strong>水平域</strong>：定义了多个系统和多个系统族中功能区域的共有部分，在子系统级上涵盖多个系统族</li></ul><hr><h3 id="三、4-1-视图模型" tabindex="-1">三、4+1 视图模型 <a class="header-anchor" href="#三、4-1-视图模型" aria-label="Permalink to &quot;三、4+1 视图模型&quot;">​</a></h3><blockquote><p>4+1 视图模型从多个视图描述软件体系结构，核心思想是<strong>关注点分离</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>视图</th><th>作用</th><th>关注点</th></tr></thead><tbody><tr><td><strong>逻辑视图</strong></td><td>描述对象模型，说明系统应提供哪些服务</td><td>功能需求（用户视角）</td></tr><tr><td><strong>过程视图</strong></td><td>捕捉设计的<strong>并发和同步</strong>特性</td><td>系统行为特性（动态视角）</td></tr><tr><td><strong>开发视图</strong></td><td>描述开发环境中软件的<strong>静态组织结构</strong></td><td>模块组织</td></tr><tr><td><strong>物理视图</strong></td><td>描述软件到硬件的映射</td><td>部署拓扑</td></tr><tr><td><strong>场景（+1）</strong></td><td><strong>用例视图</strong>，验证其他视图一致性</td><td>统一场景</td></tr></tbody></table><p><strong>视图与视角关系：</strong></p><ul><li><strong>静态视角</strong>（展示功能组织）→ 判断质量特性</li><li><strong>动态视角</strong>（展示并发行为）→ 判断系统行为特性</li><li>四个视图：逻辑视图、进程视图、实现视图、<strong>配置视图</strong></li><li>使用<strong>逻辑视图</strong>记录设计元素的功能和概念接口</li></ul><hr><h3 id="四、架构文档化" tabindex="-1">四、架构文档化 <a class="header-anchor" href="#四、架构文档化" aria-label="Permalink to &quot;四、架构文档化&quot;">​</a></h3><blockquote><p>架构文档化过程的主要输出结果是<strong>架构规格说明书</strong>和<strong>测试架构需求的质量设计说明书</strong>。</p></blockquote><p><strong>文档化原则：</strong></p><ul><li>从使用者的角度书写文档</li><li>随时保证文档是最新的</li><li>将文档分发给相关人员</li><li>针对不同背景的人员书写文档的方式不同</li></ul><hr><h3 id="五、软件复用" tabindex="-1">五、软件复用 <a class="header-anchor" href="#五、软件复用" aria-label="Permalink to &quot;五、软件复用&quot;">​</a></h3><p><strong>机会复用 vs 系统复用：</strong></p><ul><li><strong>机会复用</strong>（发现复用）：开发过程中，只要发现有可复用的资产，就进行复用</li><li><strong>系统复用</strong>（计划复用）：开发之前就进行规划，决定哪些需要复用</li></ul><p><strong>水平式重用 vs 垂直式重用：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>典型代表</th></tr></thead><tbody><tr><td><strong>水平式重用</strong></td><td>跨领域通用（应用领域无关），提供基础功能</td><td>标准函数库、通用类库</td></tr><tr><td><strong>垂直式重用</strong></td><td>面向特定领域（领域相关），包含领域知识</td><td>医学词汇表、电子商务标准、网银支付接口</td></tr></tbody></table><p><strong>复用过程的三个主要阶段：</strong></p><ol><li>构造/获取可复用的软件资产</li><li>管理可复用资产</li><li>使用可复用资产</li></ol><hr><h3 id="六、架构复审与演化" tabindex="-1">六、架构复审与演化 <a class="header-anchor" href="#六、架构复审与演化" aria-label="Permalink to &quot;六、架构复审与演化&quot;">​</a></h3><p><strong>架构复审目的：</strong> 标识潜在风险，及早发现架构设计中的缺陷和错误。复审过程中主要由<strong>用户代表与领域专家</strong>决定架构是否满足需求、质量需求是否在设计中得到体现。</p><p><strong>架构演化：</strong> 针对用户需求变化，修改应用架构满足新的需求。</p><p><strong>架构描述与需求对应：</strong></p><ul><li>架构 → 用<strong>视角与视图</strong>描述</li><li>功能需求 → 用<strong>用例</strong>描述</li><li>质量需求 → 用<strong>质量场景</strong>描述</li></ul><hr><h3 id="七、构件组装与架构失配" tabindex="-1">七、构件组装与架构失配 <a class="header-anchor" href="#七、构件组装与架构失配" aria-label="Permalink to &quot;七、构件组装与架构失配&quot;">​</a></h3><blockquote><p>🎯 架构失配主要包括三类：<strong>构件失配</strong>（基础设施/控制模型/数据模型冲突）、<strong>连接子失配</strong>（交互协议/数据格式冲突）、<strong>系统成分对全局体系结构的假设冲突</strong>。</p></blockquote><p><strong>失配分类与原因：</strong></p><table tabindex="0"><thead><tr><th>失配类型</th><th>产生原因</th><th>关键词</th></tr></thead><tbody><tr><td><strong>构件失配</strong></td><td>系统对构件基础设施、控制模型和数据模型的假设存在冲突</td><td>基础设施、控制模型、数据模型</td></tr><tr><td><strong>连接子失配</strong></td><td>系统对构件交互协议、构件连接时数据格式的假设存在冲突</td><td>交互协议、数据格式</td></tr><tr><td><strong>全局体系结构失配</strong></td><td>系统成分对全局体系结构的假设存在冲突</td><td>整体架构假设</td></tr></tbody></table><blockquote><p>⚠️ 常见坑：<strong>由构件操作不当引起的失配</strong>不属于构件组装阶段的失配问题。</p></blockquote><hr><h3 id="八、软件系统四大基本功能-三硬件构件-架构设计核心模型" tabindex="-1">八、软件系统四大基本功能 + 三硬件构件（架构设计核心模型） <a class="header-anchor" href="#八、软件系统四大基本功能-三硬件构件-架构设计核心模型" aria-label="Permalink to &quot;八、软件系统四大基本功能 + 三硬件构件（架构设计核心模型）&quot;">​</a></h3><blockquote><p>🎯 软件系统可分为四项基本功能，硬件有三类主要构件。架构设计的首要步骤是将<strong>非功能需求</strong>细化为更详细的需求。</p></blockquote><p><strong>软件系统四大基本功能（自上而下）：</strong></p><table tabindex="0"><thead><tr><th>功能</th><th>英文</th><th>说明</th></tr></thead><tbody><tr><td><strong>数据存储</strong></td><td>Data Storage</td><td>存储和检索数据，无论是小文件还是大数据库</td></tr><tr><td><strong>数据访问逻辑</strong></td><td>Data Access Logic</td><td>处理访问数据的过程，通常指 SQL 查询</td></tr><tr><td><strong>应用逻辑</strong></td><td>Application Logic</td><td>DFD、用例和功能需求中记录的业务逻辑</td></tr><tr><td><strong>表示逻辑</strong></td><td>Presentation Logic</td><td>向用户显示信息并接收用户命令</td></tr></tbody></table><p><strong>系统三类主要硬件构件：</strong></p><blockquote><p>🎯 客户端（Clients）、服务器（Servers）、网络（Network）。</p></blockquote><hr><h3 id="九、设计模式三分类" tabindex="-1">九、设计模式三分类 <a class="header-anchor" href="#九、设计模式三分类" aria-label="Permalink to &quot;九、设计模式三分类&quot;">​</a></h3><blockquote><p>🎯 设计模式按目的分为：<strong>创建型</strong>（对象实例化）、<strong>结构型</strong>（类/对象组合）、<strong>行为型</strong>（类/对象交互）。</p></blockquote><table tabindex="0"><thead><tr><th>分类</th><th>核心关注</th><th>典型例子</th></tr></thead><tbody><tr><td><strong>创建型</strong></td><td>对象实例化过程的抽象</td><td>单例（Singleton）、工厂方法</td></tr><tr><td><strong>结构型</strong></td><td>类或对象的组合方式</td><td>适配器（Adapter）、桥接（Bridge）</td></tr><tr><td><strong>行为型</strong></td><td>类或对象之间的交互和职责分配</td><td>策略（Strategy）、观察者（Observer）</td></tr></tbody></table><blockquote><p>🎯 Bridge 模式 = 将抽象与实现分离；Strategy 模式 = 算法族可互换使用。飞机模拟系统中飞行行为与起飞行为的解耦是 <strong>Strategy 模式</strong>。</p></blockquote><hr><h3 id="十、ansi-ieee-1471-2000-标准" tabindex="-1">十、ANSI/IEEE 1471-2000 标准 <a class="header-anchor" href="#十、ansi-ieee-1471-2000-标准" aria-label="Permalink to &quot;十、ANSI/IEEE 1471-2000 标准&quot;">​</a></h3><blockquote><p>该标准中使用**视图（View）<strong>描述软件架构模型，采用</strong>视角（Viewpoint）**描述某一利益相关人关注的方面，架构描述则是对所有利益相关人关注点的响应和回答。</p></blockquote><hr><h3 id="十一、4-1-视图模型" tabindex="-1">十一、4+1 视图模型 <a class="header-anchor" href="#十一、4-1-视图模型" aria-label="Permalink to &quot;十一、4+1 视图模型&quot;">​</a></h3><blockquote><p>多视图体现了<strong>关注点分离</strong>的思想。&quot;4+1&quot;模型中的&quot;1&quot;指的是<strong>统一场景（Use Case）</strong>，将 4 个视图（逻辑视图、进程视图、开发视图、物理视图）串联起来。</p></blockquote><hr><h3 id="十二、软件系统四项基本功能-划分视角" tabindex="-1">十二、软件系统四项基本功能（划分视角） <a class="header-anchor" href="#十二、软件系统四项基本功能-划分视角" aria-label="Permalink to &quot;十二、软件系统四项基本功能（划分视角）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>视角</th><th>关注点</th><th style="text-align:center;">能否判断质量特性</th></tr></thead><tbody><tr><td><strong>静态视角（逻辑视图）</strong></td><td>功能组织</td><td style="text-align:center;">✅</td></tr><tr><td><strong>动态视角（进程视图）</strong></td><td>并发行为 → 系统行为特性</td><td style="text-align:center;">✅</td></tr><tr><td><strong>配置视角（部署视图）</strong></td><td>软件到硬件的映射</td><td style="text-align:center;">❌</td></tr></tbody></table><hr><h3 id="十三、架构文档化" tabindex="-1">十三、架构文档化 <a class="header-anchor" href="#十三、架构文档化" aria-label="Permalink to &quot;十三、架构文档化&quot;">​</a></h3><p>ABSD 方法中文档化核心输出：</p><ul><li><strong>体系结构规格说明</strong></li><li><strong>质量设计说明书</strong></li></ul><blockquote><p>架构复审必须邀请<strong>独立于系统开发的外部人员</strong>参与，目的是<strong>标识潜在风险，及早发现架构设计中的缺陷和错误</strong>。</p></blockquote><hr><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p><strong>[Q1] 构件分类方法</strong></p><p>基于构件的软件开发中，构件分类方法可以归纳为三大类：（请作答此空）根据领域分析的结果将应用领域的概念按照从抽象到具体的顺序逐次分解为树形或有向无回路图结构。</p><ul><li><strong>A.</strong> 关键字分类法</li><li><strong>B.</strong> 刻面分类法</li><li><strong>C.</strong> 语义匹配法</li><li><strong>D.</strong> 超文本方法</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q2] 设计模式分类</strong></p><p>设计模式按照目的可以划分为三类，其中（请作答此空）模式是对对象实例化过程的抽象。</p><ul><li><strong>A.</strong> 创建型</li><li><strong>B.</strong> 结构型</li><li><strong>C.</strong> 行为型</li><li><strong>D.</strong> 功能型</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q3] ANSI/IEEE 1471-2000</strong></p><p>在该标准中，（请作答此空）这一概念主要用于描述软件架构模型。</p><ul><li><strong>A.</strong> 上下文</li><li><strong>B.</strong> 架构风格</li><li><strong>C.</strong> 组件</li><li><strong>D.</strong> 视图</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q4] ATAM 评估方法</strong></p><p>ATAM 主要在系统开发之前，针对性能、（请作答此空）、安全性和可修改性等质量属性进行评价和折中。</p><ul><li><strong>A.</strong> 可测试性</li><li><strong>B.</strong> 可移植性</li><li><strong>C.</strong> 可用性</li><li><strong>D.</strong> 易用性</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q5] 飞机模拟系统设计模式</strong></p><p>飞机飞行模拟系统，类 AirCraft、FlyBehavior、TakeOffBehavior，应采用的模式是（ ）。</p><ul><li><strong>A.</strong> Bridge模式</li><li><strong>B.</strong> Composite模式</li><li><strong>C.</strong> Observer模式</li><li><strong>D.</strong> Strategy模式</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q6] 标识构件范畴（不属于）</strong></p><p>以下活动中，不属于软件架构需求过程中标识构件范畴的是（ ）。</p><ul><li><strong>A.</strong> 生成类图</li><li><strong>B.</strong> 对类图进行分组</li><li><strong>C.</strong> 对类图进行测试</li><li><strong>D.</strong> 将类合并打包</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q7] ABSD 描述方式</strong></p><p>ABSD 方法强调采用（1）来描述软件架构，采用（2）来描述需求。</p><ul><li><strong>A.</strong> 类图和序列图</li><li><strong>B.</strong> 视角与视图</li><li><strong>C.</strong> 构件和类图</li><li><strong>D.</strong> 构件与功能</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q8] 质量属性场景</strong></p><p>交易平台必须在 800 ms 内完成交易请求，实现并提高该质量属性的架构设计策略不包括（ ）。</p><ul><li><strong>A.</strong> 采用优先级调度队列</li><li><strong>B.</strong> 引入并发处理</li><li><strong>C.</strong> 优化相关进程的CPU占用率</li><li><strong>D.</strong> 设置进程监视器</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q9] ABSD 三个基础</strong></p><p>下面不属于 ABSD 方法的三个基础的是（ ）。</p><ul><li><strong>A.</strong> 功能的分解</li><li><strong>B.</strong> 通过选择架构风格来实现质量和业务需求</li><li><strong>C.</strong> 软件模板的使用</li><li><strong>D.</strong> 强调由业务、质量和功能需求的组合驱动架构设计</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q10] 多视图思想</strong></p><p>多视图是一种描述软件体系结构的重要途径，体现了（ ）的思想。</p><ul><li><strong>A.</strong> 关注点分离</li><li><strong>B.</strong> 面向对象</li><li><strong>C.</strong> 模型驱动</li><li><strong>D.</strong> UML</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q11] 4+1 模型中的&quot;1&quot;</strong></p><p>4+1 模型中，&quot;1&quot;指的是（ ）。</p><ul><li><strong>A.</strong> 统一场景</li><li><strong>B.</strong> 开发视图</li><li><strong>C.</strong> 逻辑视图</li><li><strong>D.</strong> 物理视图</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q12] ABSD 驱动因素</strong></p><p>ABSD 方法是体系结构驱动，是指构成体系结构的（ ）的组合驱动的。</p><ul><li><strong>A.</strong> 产品、功能需求和设计活动</li><li><strong>B.</strong> 商业、质量和功能需求</li><li><strong>C.</strong> 商业、产品和功能需求</li><li><strong>D.</strong> 商业、质量和设计活动</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q13] ABSD 细化目标</strong></p><p>ABSD 方法体系结构通过细化，直到能产生（ ）。</p><ul><li><strong>A.</strong> 软件产品和代码</li><li><strong>B.</strong> 软件构件和类</li><li><strong>C.</strong> 软件构件和连接件</li><li><strong>D.</strong> 类和软件代码</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q14] 静态视角</strong></p><p>展示功能组织的（1）能判断质量特性。</p><ul><li><strong>A.</strong> 静态视角</li><li><strong>B.</strong> 动态视角</li><li><strong>C.</strong> 多维视角</li><li><strong>D.</strong> 功能视角</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q15] 动态视角</strong></p><p>展示并发行为的（2）能判断系统行为特性。</p><ul><li><strong>A.</strong> 开发视角</li><li><strong>B.</strong> 动态视角</li><li><strong>C.</strong> 部署视角</li><li><strong>D.</strong> 功能视角</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q16] 配置视角</strong></p><p>选择的特定视角或视图也就是逻辑视图、进程视图、实现视图和（3）。</p><ul><li><strong>A.</strong> 开发视图</li><li><strong>B.</strong> 配置视图</li><li><strong>C.</strong> 部署视图</li><li><strong>D.</strong> 物理视图</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q17] 逻辑视图</strong></p><p>使用（4）来记录设计元素的功能和概念接口。</p><ul><li><strong>A.</strong> 逻辑视图</li><li><strong>B.</strong> 物理视图</li><li><strong>C.</strong> 部署视图</li><li><strong>D.</strong> 用例视图</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q18] ABSD 功能需求工具</strong></p><p>ABSD 方法中描述功能需求的工具是（1）。</p><ul><li><strong>A.</strong> 质量场景</li><li><strong>B.</strong> 用例</li><li><strong>C.</strong> 软件模板</li><li><strong>D.</strong> 状态图</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q19] 架构文档化核心输出</strong></p><p>ABSDM 模型中，架构文档化的核心输出是（2）与质量设计说明书。</p><ul><li><strong>A.</strong> 用户操作手册</li><li><strong>B.</strong> 体系结构规格说明</li><li><strong>C.</strong> 数据库ER图</li><li><strong>D.</strong> 代码注释规范</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q20] 架构复审角色</strong></p><p>架构复审必须邀请的角色是（3）。</p><ul><li><strong>A.</strong> 项目经理</li><li><strong>B.</strong> 开发团队成员</li><li><strong>C.</strong> 外部领域专家</li><li><strong>D.</strong> 测试工程师</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q21] 文档化输出结果</strong></p><p>ABSD 方法中体系结构文档化的主要输出结果是（1）。</p><ul><li><strong>A.</strong> 体系结构规格说明和测试体系结构需求的质量设计说明书</li><li><strong>B.</strong> 体系结构复审报告和测试用例</li><li><strong>C.</strong> 体系结构实现代码和测试报告</li><li><strong>D.</strong> 体系结构演化计划和测试计划</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q22] 复审目的</strong></p><p>体系结构复审的主要目的是（2）。</p><ul><li><strong>A.</strong> 编写代码</li><li><strong>B.</strong> 标识潜在的风险，发现体系结构设计中的缺陷和错误</li><li><strong>C.</strong> 测试构件的功能性</li><li><strong>D.</strong> 更新构件的相互作用</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q23] 描述质量需求</strong></p><p>用（3）描述质量需求。</p><ul><li><strong>A.</strong> 用例</li><li><strong>B.</strong> 质量场景</li><li><strong>C.</strong> 体系结构风格</li><li><strong>D.</strong> 软件模板</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q24] 架构需求获取来源（不包括）</strong></p><p>ABSDM 模型中架构需求获取的来源不包括（1）。</p><ul><li><strong>A.</strong> 构件性能指标</li><li><strong>B.</strong> 系统商业目标</li><li><strong>C.</strong> 开发人员商业目标</li><li><strong>D.</strong> 系统质量目标</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q25] 架构实现基础依据</strong></p><p>架构实现的基础依据是（2）与质量设计说明书。</p><ul><li><strong>A.</strong> 用户原始需求文档</li><li><strong>B.</strong> 文档化后的架构说明书</li><li><strong>C.</strong> 商业目标分析报告</li><li><strong>D.</strong> 竞品系统分析</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q26] 构件变动前需</strong></p><p>架构演化步骤中，&quot;构件变动&quot;前需（3）。</p><ul><li><strong>A.</strong> 直接修改代码</li><li><strong>B.</strong> 制定演化计划</li><li><strong>C.</strong> 技术评审</li><li><strong>D.</strong> 测试性能</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q27] ADD 主要输入</strong></p><p>属性驱动的软件设计方法（ADD）的主要输入是什么（ ）。</p><ul><li><strong>A.</strong> 系统功能需求</li><li><strong>B.</strong> 质量属性场景</li><li><strong>C.</strong> 用户界面原型</li><li><strong>D.</strong> 系统架构图</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q28] ABSD 三个基础（不属于）</strong></p><p>以下哪项不属于 ABSD 方法的三个基础之一（ ）。</p><ul><li><strong>A.</strong> 功能分解</li><li><strong>B.</strong> 体系结构风格选择</li><li><strong>C.</strong> 软件模板使用</li><li><strong>D.</strong> 需求获取</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q29] ABSDM 子过程数</strong></p><p>ABSDM 模型将软件过程划分为几个子过程（ ）。</p><ul><li><strong>A.</strong> 4个子过程</li><li><strong>B.</strong> 5个子过程</li><li><strong>C.</strong> 6个子过程</li><li><strong>D.</strong> 7个子过程</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q30] ABSD 方法描述</strong></p><p>关于 ABSD 方法，以下描述正确的是（ ）。</p><ul><li><strong>A.</strong> ABSD是自底向上的设计方法</li><li><strong>B.</strong> ABSD是自顶向下、递归细化的方法</li><li><strong>C.</strong> ABSD方法直接产生代码</li><li><strong>D.</strong> ABSD方法不涉及软件构件和类的生成</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q31] 质量需求描述方式</strong></p><p>ABSD 方法中哪种描述方式用于表示质量需求（ ）。</p><ul><li><strong>A.</strong> 视角与视图</li><li><strong>B.</strong> 用例</li><li><strong>C.</strong> 质量场景</li><li><strong>D.</strong> 功能分解</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q32] 驱动因素（不属于）</strong></p><p>以下哪个因素不是驱动软件架构设计的主要需求（ ）。</p><ul><li><strong>A.</strong> 商业需求</li><li><strong>B.</strong> 质量需求</li><li><strong>C.</strong> 功能需求</li><li><strong>D.</strong> 技术需求</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q33] 标识构件第一步</strong></p><p>在 ABSD 模型中，在标识构件的过程中第一步是（ ）。</p><ul><li><strong>A.</strong> 对类进行分组</li><li><strong>B.</strong> 编写构件的接口</li><li><strong>C.</strong> 把类打包成构件</li><li><strong>D.</strong> 生成类图</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q34] 文档化输出</strong></p><p>在 ABSD 模型中，体系结构文档化过程的主要输出结果是（ ）。</p><ul><li><strong>A.</strong> 安装说明手册</li><li><strong>B.</strong> 需求规格说明书</li><li><strong>C.</strong> 架构规格说明书和质量设计说明书</li><li><strong>D.</strong> 项目管理计划</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q35] 评审参与者</strong></p><p>体系结构设计的评审必须邀请（ ）参与。</p><ul><li><strong>A.</strong> 所有项目团队成员</li><li><strong>B.</strong> 质量管理人员</li><li><strong>C.</strong> 独立于系统开发的外部人员</li><li><strong>D.</strong> 项目经理和高级开发人员</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q36] 需求获取来源</strong></p><p>ABSD 方法中需求主要来自（1）。</p><ul><li><strong>A.</strong> 用户功能需求、系统性能需求、安全合规需求</li><li><strong>B.</strong> 技术可行性、项目预算、开发周期</li><li><strong>C.</strong> 质量目标、系统的商业目标和系统开发人员的商业目标</li><li><strong>D.</strong> 市场竞品分析、技术趋势、团队技术栈</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q37] 标识构件顺序</strong></p><p>标识构件的正确顺序是（2）。</p><ul><li><strong>A.</strong> 生成类图 → 对类进行分组 → 把类打包成构件</li><li><strong>B.</strong> 对类进行分组 → 生成类图 → 把类打包成构件</li><li><strong>C.</strong> 把类打包成构件 → 生成类图 → 对类进行分组</li><li><strong>D.</strong> 生成类图 → 把类打包成构件 → 对类进行分组</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q38] 体系结构演化第一步</strong></p><p>在体系结构演化过程中，首先应该（3）。</p><ul><li><strong>A.</strong> 直接修改代码</li><li><strong>B.</strong> 制定详细的开发计划</li><li><strong>C.</strong> 需求变化归类</li><li><strong>D.</strong> 更新构件的相互作用</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q39] ABSD 方法论文</strong></p><p>论基于架构的软件设计方法及应用。ABSD 方法以构成软件架构的商业、质量和功能需求等要素来驱动整个软件开发过程。</p><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p><strong>请看解析</strong>：ABSD 是自顶向下、递归细化的方法，以功能分解为基础，通过选择架构风格实现质量/商业需求，使用软件模板。适用于产品线或长生命周期系统。</p></div></details><hr><p><strong>[Q40] 软件架构复用类型（机会复用）</strong></p><p>在软件架构复用中，(1)是指开发过程中，只要发现有可复用的资产，就对其进行复用。</p><ul><li><strong>A.</strong> 发现复用</li><li><strong>B.</strong> 机会复用</li><li><strong>C.</strong> 资产复用</li><li><strong>D.</strong> 过程复用</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q41] 软件架构复用类型（系统复用）</strong></p><p>(2)是指在开发之前，就要进行规划，以决定哪些需要复用。</p><ul><li><strong>A.</strong> 预期复用</li><li><strong>B.</strong> 计划复用</li><li><strong>C.</strong> 资产复用</li><li><strong>D.</strong> 系统复用</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q42] DSSA 领域模型</strong></p><p>DSSA 中领域模型是（ ）阶段的主要目标。</p><ul><li><strong>A.</strong> 领域设计</li><li><strong>B.</strong> 领域实现</li><li><strong>C.</strong> 领域分析</li><li><strong>D.</strong> 领域工程</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q43] 横向重用</strong></p><p>软件的横向重用是指重用不同应用领域中的软件元素。 （ ）是一种横向重用机制。</p><ul><li><strong>A.</strong> 产品文档</li><li><strong>B.</strong> 行业词汇表</li><li><strong>C.</strong> 通用算法库</li><li><strong>D.</strong> 业务流程</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q44] 不属于软件复用对象</strong></p><p>以下不属于软件复用对象的是（1）。</p><ul><li><strong>A.</strong> 测试用例</li><li><strong>B.</strong> 项目计划模板</li><li><strong>C.</strong> 临时生成的中间数据</li><li><strong>D.</strong> 缺陷消除方案</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q45] 复用第一步</strong></p><p>软件架构复用的基本过程第一步是（2）。</p><ul><li><strong>A.</strong> 管理复用资产</li><li><strong>B.</strong> 使用复用资产</li><li><strong>C.</strong> 构建/获取复用资产</li><li><strong>D.</strong> 评估复用效果</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q46] 复用类型</strong></p><p>软件架构复用的类型包括（1）。</p><ul><li><strong>A.</strong> 函数复用和系统复用</li><li><strong>B.</strong> 库的复用和包的复用</li><li><strong>C.</strong> 类的复用和机会复用</li><li><strong>D.</strong> 机会复用和系统复用</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q47] 管理可复用资产</strong></p><p>管理可复用资产最重要的是（2）。</p><ul><li><strong>A.</strong> 构件库</li><li><strong>B.</strong> 函数库</li><li><strong>C.</strong> 设计文档</li><li><strong>D.</strong> 用户需求</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q48] 可复用软件资产</strong></p><p>以下属于可复用的软件资产的是（1）。</p><ul><li><strong>A.</strong> 熟练的产品线编程人员</li><li><strong>B.</strong> 未经验证的代码片段</li><li><strong>C.</strong> 临时生成的测试数据</li><li><strong>D.</strong> 仅限当前项目使用的工具</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q49] 复用资产管理关键</strong></p><p>复用资产管理的关键问题在于（2）。</p><ul><li><strong>A.</strong> 构件分类与检索</li><li><strong>B.</strong> 强制团队使用资产</li><li><strong>C.</strong> 禁止资产更新</li><li><strong>D.</strong> 资产管理过程存在损耗</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q50] 软件产品线核心组成</strong></p><p>软件产品线的核心组成（ ）。</p><ul><li><strong>A.</strong> 核心资源＋产品集合</li><li><strong>B.</strong> 架构设计＋代码库</li><li><strong>C.</strong> 开发团队＋管理流程</li><li><strong>D.</strong> 需求分析＋测试用例</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q51] 产品线必要条件（不包括）</strong></p><p>软件产品线实施成功的必要条件不包括（ ）。</p><ul><li><strong>A.</strong> 对该领域的产品开发具备长期积累的深入经验</li><li><strong>B.</strong> 建立一个用于构建产品的好的核心资源库</li><li><strong>C.</strong> 采用敏捷开发方法进行快速迭代</li><li><strong>D.</strong> 创建稳定、可靠的产品线架构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q52] 标准函数库重用类型</strong></p><p>在软件重用中，标准函数库属于（ ）。</p><ul><li><strong>A.</strong> 垂直式重用</li><li><strong>B.</strong> 水平式重用</li><li><strong>C.</strong> 领域特定重用</li><li><strong>D.</strong> 构件组装重用</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q53] 软件产品线特点</strong></p><p>关于软件产品线的特点，下列描述正确的是（ ）。</p><ul><li><strong>A.</strong> 以数据为中心、特定领域、技术驱动、过程支持</li><li><strong>B.</strong> 过程驱动、特定领域、以技术支持、以架构为中心</li><li><strong>C.</strong> 架构驱动、通用领域、以过程支持、以技术为中心</li><li><strong>D.</strong> 技术驱动、通用领域、以架构支持、以过程为中心</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q54] 不属于软件元素</strong></p><p>下列选项中，不属于软件重用中软件元素的是（ ）。</p><ul><li><strong>A.</strong> 需求分析文档</li><li><strong>B.</strong> 程序代码</li><li><strong>C.</strong> 硬件设备配置</li><li><strong>D.</strong> 测试用例</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q55] 产品线必要条件（再问）</strong></p><p>以下哪项不是软件产品线实施成功的必要条件（ ）。</p><ul><li><strong>A.</strong> 对该领域的产品开发具备长期积累的深入经验</li><li><strong>B.</strong> 建立一个用于构建产品的好的核心资源库</li><li><strong>C.</strong> 创建稳定、可靠的产品线架构</li><li><strong>D.</strong> 设立独立的核心资源小组</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q56] 产品线演化方式</strong></p><p>某公司决定将其现有的多个独立软件产品整合成一个软件产品线。这种做法属于（ ）。</p><ul><li><strong>A.</strong> 将现有产品演化为产品线</li><li><strong>B.</strong> 用软件产品线替代现有产品集</li><li><strong>C.</strong> 全新软件产品线的演化</li><li><strong>D.</strong> 全新软件产品线的开发</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q57] 产品线不正确描述</strong></p><p>以下关于软件产品线的描述，哪一项是不正确的（ ）。</p><ul><li><strong>A.</strong> 软件产品线是一个共享公共特征集的产品集合</li><li><strong>B.</strong> 软件产品线能有效提高生产率和质量，缩短开发时间</li><li><strong>C.</strong> 软件产品线的特点包括过程驱动和以架构为中心</li><li><strong>D.</strong> 软件产品线适用于所有类型的软件开发项目</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q58] 软件重用概念</strong></p><p>以下哪项最准确地描述了软件重用的概念（ ）。</p><ul><li><strong>A.</strong> 仅在同一项目中多次使用相同的代码片段</li><li><strong>B.</strong> 在不同的软件开发过程中重复使用相同或相似的软件元素</li><li><strong>C.</strong> 只在特定领域内重用专门的软件组件</li><li><strong>D.</strong> 仅指重用程序代码和设计文档</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q59] 水平式重用</strong></p><p>在软件重用的分类中，通用领域的重用可以应用于任何软件项目，称为（ ）。</p><ul><li><strong>A.</strong> 垂直式重用</li><li><strong>B.</strong> 水平式重用</li><li><strong>C.</strong> 局部式重用</li><li><strong>D.</strong> 专业式重用</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q60] 构件分类和检索</strong></p><p>软件架构复用的基本过程中，构件分类和构件检索属于（ ）阶段。</p><ul><li><strong>A.</strong> 构造/获取可复用的软件资产</li><li><strong>B.</strong> 管理可复用资产</li><li><strong>C.</strong> 使用可复用的资产</li><li><strong>D.</strong> 定制可复用资产</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q61] 复用优势（不正确）</strong></p><p>以下关于软件架构复用的优势，哪一项是不正确的（ ）。</p><ul><li><strong>A.</strong> 减少开发时间</li><li><strong>B.</strong> 提高产品质量</li><li><strong>C.</strong> 增加开发成本</li><li><strong>D.</strong> 简化产品维护</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q62] 计划复用</strong></p><p>在软件架构复用中，在开发之前就进行规划决定复用类型的称为（ ）。</p><ul><li><strong>A.</strong> 机会复用</li><li><strong>B.</strong> 系统复用</li><li><strong>C.</strong> 代码复用</li><li><strong>D.</strong> 构件复用</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q63] 复用范围</strong></p><p>关于软件复用的范围，以下说法正确的是（ ）。</p><ul><li><strong>A.</strong> 软件复用仅限于代码级复用</li><li><strong>B.</strong> 软件复用主要包括代码和文档的复用</li><li><strong>C.</strong> 软件复用包括从领域知识到开发工具的各个方面</li><li><strong>D.</strong> 软件复用仅限于设计和测试阶段</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q64] 系统复用特征</strong></p><p>以下（1）最符合&quot;系统复用&quot;的特征。</p><ul><li><strong>A.</strong> 依赖于开发人员的个人经验和临场发现</li><li><strong>B.</strong> 在项目启动后，根据遇到的具体问题寻找可复用方案</li><li><strong>C.</strong> 在项目规划和设计阶段，就制定明确的复用目标和计划</li><li><strong>D.</strong> 主要复用他人项目遗留下来的、未经整理的代码</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q65] 敏捷团队复用类型</strong></p><p>在一个遵循敏捷开发模式的小型团队中，更可能频繁发生（2）。</p><ul><li><strong>A.</strong> 系统复用</li><li><strong>B.</strong> 机会复用</li><li><strong>C.</strong> 架构模式复用</li><li><strong>D.</strong> 需求规约复用</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q66] 功能模块复用架构思路</strong></p><p>结合你的系统架构设计经验，简要说明该项目中的5个功能模块在软件复用方面的基本架构思路。</p><details class="callout callout-info"><summary class="callout-title"><span class="callout-icon">ℹ️</span>材料</summary><div class="callout-body"><p>试题四：XX行业管理信息系统由公共信息管理模块、系统管理维护模块、资质管理模块、企业信息管理模块和系统扩展接口模块等5大功能模块组成。</p></div></details><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与思路</summary><div class="callout-body"><p><strong>复用架构思路</strong>：公共信息管理模块和系统管理维护模块通过配置文件加载建设方信息，降低耦合度易复用。资质管理、企业信息管理、系统扩展接口等与建设方密切相关的模块，尽力降低耦合度使复用代价最小化。</p></div></details><hr><p><strong>[Q67] 可复用构件属性</strong></p><p>软件复用包括两个相关过程：可复用软件构件的开发；基于可复用构件的应用系统构造。可复用构件应具备哪些属性？</p><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>可复用构件属性包括：<strong>可用性</strong>（易于理解和使用）、<strong>质量</strong>（正确工作）、<strong>适应性</strong>（可参数化配置）、<strong>可移植性</strong>（跨平台/环境）、<strong>可变性</strong>（可变部分适当调节）。</p></div></details>',410)])])}const m=l(n,[["render",a]]);export{e as __pageData,m as default};
